grant execute on function procurement_private.weekly_intervals(),procurement_private.weekly_stamp(text),procurement_private.work_hours(timestamptz,timestamptz) to service_role;
create function public.trackers_common_snapshot(p_week_start date) returns jsonb language sql stable security invoker set search_path='' as $$
with params as(select (p_week_start-(extract(isodow from p_week_start)::int-1)) week_start),
people as(select id,lower(btrim(email)) email,full_name from public.employees where is_active and lower(btrim(email)) in ('ankesh.k@brightbots.in','amandeep@brightbots.in','quality@brightbots.in','amit.k@brightbots.in','ramesh@brightbots.in','vinay@brightbots.in')),
intervals as(select * from procurement_private.weekly_intervals()),
work as(select i.id,i.request_id,i.current_stage,procurement_private.work_hours(x.started_at,now()) hours,case i.current_stage when 'Request Approval' then 8 when 'Quotation' then 24 when 'Vendor Approval' then 8 when 'PO' then 6 when 'Fund Approval' then 4 when 'Payment' then 16 when 'Dispatch' then 24 when 'QC' then 6 else 8 end tat from public.request_items i left join intervals x on x.item_id=i.id and x.stage=case when i.current_stage in ('Invoice','Accounting') then 'Invoice + Accounting' else i.current_stage end and x.completed_at is null where i.current_stage not in ('Completed','Rejected')),
assigned as(select distinct p.id employee_id,w.id,w.hours,w.tat from work w join public.stage_owners s on s.stage=w.current_stage join people p on p.id=s.employee_id),
workload as(select employee_id,count(*) open,count(*) filter(where hours>tat) overdue,count(*) filter(where hours is null) unmeasured_open from assigned group by employee_id),
completed as(select e.*,x.completed_at final_end from public.stage_events e join intervals x on x.item_id=e.item_id and x.stage=e.stage cross join params z where x.completed_at>=z.week_start::timestamp at time zone 'Asia/Kolkata' and x.completed_at<(z.week_start+7)::timestamp at time zone 'Asia/Kolkata'),
scores as(select p.id,count(*) filter(where c.color='Green') green,count(*) filter(where c.color='Yellow') yellow,count(*) filter(where c.color='Red') red,count(*) filter(where c.color is not null) measured,count(*) filter(where c.attribution not in ('verified_stage_owner_action','verified_admin_action')) configured_attribution from completed c join people p on p.id=any(c.owner_ids) group by p.id),
rows as(select p.email,p.full_name name,''::text team,coalesce(w.open,0) open,coalesce(w.overdue,0) overdue,coalesce(w.unmeasured_open,0) unmeasured_open,coalesce(s.green,0) green,coalesce(s.yellow,0) yellow,coalesce(s.red,0) red,coalesce(s.measured,0) measured,coalesce(s.configured_attribution,0) configured_attribution,(select coalesce(string_agg(distinct o.stage,', ' order by o.stage),'') from public.stage_owners o where o.employee_id=p.id) stages from people p left join workload w on w.employee_id=p.id left join scores s on s.id=p.id)
select jsonb_build_object('source','procurement','generated_at',now(),'week_start',(select week_start from params),'week_end',(select week_start+6 from params),'revision',(select revision from trackers_private.change_signal where id),'people',coalesce((select jsonb_agg(to_jsonb(r) order by name) from rows r),'[]'::jsonb),'summary',jsonb_build_object('open',(select count(*) from work),'overdue',(select count(*) from work where hours>tat),'green',(select count(*) from completed where color='Green'),'yellow',(select count(*) from completed where color='Yellow'),'red',(select count(*) from completed where color='Red'),'measured',(select count(*) from completed where color is not null)),'rules','Completed stage TAT measurements in the selected Monday–Sunday week. Green within TAT; yellow within TAT + 8 working hours; red beyond. Historical configured-owner attribution does not verify the actor. Shared QC workload/results appear for each responsible employee; source totals deduplicate items/stages.');
$$;
revoke all on function public.trackers_common_snapshot(date) from public,anon,authenticated;
grant execute on function public.trackers_common_snapshot(date) to service_role;
create trigger trackers_items_changed after insert or update or delete on public.request_items for each statement execute function trackers_private.signal_change();
create trigger trackers_events_changed after insert or update or delete on public.stage_events for each statement execute function trackers_private.signal_change();
create trigger trackers_employees_changed after insert or update or delete on public.employees for each statement execute function trackers_private.signal_change();
create trigger trackers_owners_changed after insert or update or delete on public.stage_owners for each statement execute function trackers_private.signal_change();
create trigger trackers_targets_changed after insert or update or delete on public.procurement_weekly_targets for each statement execute function trackers_private.signal_change();
